<template><div><div class="row" style="justify-content:space-between"><div><h1>Hisobotlar</h1><p class="muted">Kunlik, haftalik, oylik yoki ixtiyoriy davr bo‘yicha tushum.</p></div><a class="btn primary" :href="exportHref" download>⬇ Excel yuklash</a></div><div class="card filters"><div><label class="muted">Dan</label><input v-model="from" type="date" class="input"></div><div><label class="muted">Gacha</label><input v-model="to" type="date" class="input"></div><div><label class="muted">To‘lov</label><select v-model="payment" class="input"><option value="">Barchasi</option><option value="card">Plastik / karta</option><option value="contract">Shartnoma</option></select></div><button class="btn primary" @click="load">Ko‘rsatish</button></div><div class="grid g4" style="margin-top:16px"><div class="card"><div class="muted">Buyurtmalar</div><h2>{{summary.orders}}</h2></div><div class="card"><div class="muted">Mijozlar</div><h2>{{summary.patients}}</h2></div><div class="card"><div class="muted">Tushum</div><h2>{{money(summary.revenue)}} so‘m</h2></div><div class="card"><div class="muted">Shartnoma tushumi</div><h2>{{money(contractTotal)}} so‘m</h2></div></div><div class="grid g2" style="margin-top:16px"><div v-for="p in summary.byPayment" :key="p.paymentType" class="card"><div class="muted">{{payName(p.paymentType)}} · {{p.count}} ta</div><h3>{{money(p.total)}} so‘m</h3></div></div><div class="card" style="margin-top:16px"><h3>Operatsiyalar</h3><div style="overflow:auto"><table class="table"><thead><tr><th>#</th><th>Mijoz</th><th>Summa</th><th>To‘lov</th><th>Xizmat holati</th><th>Sana</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.displayId}}</td><td>{{r.client}}</td><td>{{money(r.total)}} so‘m</td><td>{{payName(r.paymentType)}}</td><td>{{r.items.every((i:any)=>i.serviceStatus==='completed')?'Yakunlangan':'Jarayonda'}}</td><td>{{fmt(r.createdAt)}}</td></tr></tbody></table></div></div></div></template>
<script setup lang="ts">
const {request}=useApi();const summary=ref<any>({orders:0,patients:0,revenue:0,byPayment:[]});const rows=ref<any[]>([]);const from=ref(''),to=ref(''),payment=ref('');const money=(n:number)=>new Intl.NumberFormat('uz-UZ').format(n);const fmt=(d:string)=>new Date(d).toLocaleString('uz-UZ');const payName=(x:string)=>({card:'Plastik / karta',contract:'Shartnoma',pending:'Jarayonda'} as any)[x]||x;const qs=computed(()=>`from=${from.value}&to=${to.value}`);const exportHref=computed(()=>`/api/v1/reports/export?from=${from.value}&to=${to.value}`);const contractTotal=computed(()=>summary.value.byPayment?.find((x:any)=>x.paymentType==='contract')?.total||0);const load=async()=>{summary.value=await request('/reports/summary?'+qs.value);rows.value=await request('/reports/detailed?'+qs.value+(payment.value?`&paymentType=${payment.value}`:''))};onMounted(load)
</script>
